<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { getAccessToken } from '@/api/client'
import { genTypeApi, resourceApi, shortDramaApi, workflowApi, type CompiledShotTask, type DramaTake, type ShotProduction, type Storyboard } from '@/api/modules'
import GlassCard from '@/v2/components/GlassCard.vue'
import MediaViewer from '@/v2/components/MediaViewer.vue'
import StatusBadge from '@/v2/components/StatusBadge.vue'
import V2Button from '@/v2/components/V2Button.vue'
import { statusMeta } from '@/v2/features/tasks/model'

const route=useRoute(),router=useRouter(),projectId=computed(()=>Number(route.params.id))
const board=ref<Storyboard|null>(null),types=ref<any[]>([]),workflows=ref<any[]>([]),production=ref<ShotProduction|null>(null)
const selected=ref(new Set<number>()),activeShotId=ref<number|null>(null),generationTypeId=ref<number|null>(null),workflowVersionId=ref<number|null>(null)
const compiled=ref<CompiledShotTask[]>([]),filter=ref<'all'|'ready'|'draft'>('all'),loading=ref(true),working=ref(false),error=ref(''),notice=ref('')
const thumbs=ref<Record<number,string>>({}),preview=ref<any|null>(null),compare=ref(new Set<number>())
let poll:ReturnType<typeof setInterval>|null=null
const shots=computed(()=>board.value?.episodes.flatMap(episode=>episode.scenes.flatMap(scene=>scene.shots.map(shot=>({shot,scene:scene.scene,episode:episode.episode}))))||[])
const visible=computed(()=>shots.value.filter(item=>filter.value==='all'||item.shot.status===filter.value))
const activeShot=computed(()=>shots.value.find(item=>item.shot.id===activeShotId.value)?.shot||null)
const activeType=computed(()=>types.value.find(item=>item.id===generationTypeId.value))
const hasRunning=computed(()=>production.value?.tasks.some(item=>['PENDING','DISPATCHING','QUEUED','RUNNING','FINALIZING'].includes(item.task_status)))
const mediaLabel=(value:string)=>value==='image'?'图片':value==='video'?'视频':'音频'
const msg=(event:any,fallback:string)=>event.response?.data?.detail||event.message||fallback

async function load(){loading.value=true;error.value='';try{const [story,typeList]=await Promise.all([shortDramaApi.storyboard(projectId.value),genTypeApi.list({enabled:true})]);board.value=story;types.value=typeList;if(!activeShotId.value&&shots.value.length)activeShotId.value=shots.value[0].shot.id;if(!generationTypeId.value&&types.value.length)generationTypeId.value=types.value.find(item=>item.media_type==='video')?.id||types.value[0].id;await loadWorkflows();await loadProduction()}catch(event:any){error.value=msg(event,'镜头生产加载失败')}finally{loading.value=false}}
async function loadWorkflows(){const type=activeType.value;if(!type){workflows.value=[];workflowVersionId.value=null;return}workflows.value=(await workflowApi.list({generation_type_code:type.code})).filter((item:any)=>item.status==='active'&&item.current_version_id);workflowVersionId.value=workflows.value.find((item:any)=>item.id===type.default_workflow_id)?.current_version_id||workflows.value[0]?.current_version_id||null}
async function loadProduction(){if(!activeShotId.value){production.value=null;return}production.value=await shortDramaApi.shotProduction(projectId.value,activeShotId.value);await loadThumbs(production.value.takes)}
async function loadThumbs(takes:DramaTake[]){for(const take of takes){if(take.resource.media_type==='audio'||thumbs.value[take.resource_id])continue;try{const response=await fetch(resourceApi.thumbUrl(take.resource_id),{headers:{Authorization:`Bearer ${getAccessToken()||''}`}});if(response.ok)thumbs.value[take.resource_id]=URL.createObjectURL(await response.blob())}catch{}}}
function toggle(id:number){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
function chooseShot(id:number){activeShotId.value=id;void loadProduction()}
async function compile(){const ids=selected.value.size?[...selected.value]:activeShotId.value?[activeShotId.value]:[];if(!ids.length||!generationTypeId.value)return;working.value=true;error.value='';notice.value='';try{compiled.value=await shortDramaApi.compileProduction(projectId.value,{shot_ids:ids,generation_type_id:generationTypeId.value,workflow_version_id:workflowVersionId.value});notice.value=`已编译 ${compiled.value.length} 个镜头，请检查提示词和参数后执行。`}catch(event:any){error.value=msg(event,'参数编译失败')}finally{working.value=false}}
async function createTasks(){if(!compiled.value.length||!generationTypeId.value)return;working.value=true;error.value='';try{const result=await shortDramaApi.createProductionTasks(projectId.value,{shot_ids:compiled.value.map(item=>item.shot_id),generation_type_id:generationTypeId.value,workflow_version_id:workflowVersionId.value,shot_parameter_overrides:Object.fromEntries(compiled.value.map(item=>[item.shot_id,item.params])),idempotency_key:crypto.randomUUID(),submit:true,save_as_project_default:false});notice.value=`已创建 ${result.created_task_ids.length} 个任务${result.existing_task_ids.length?`，复用 ${result.existing_task_ids.length} 个任务`:''}`;compiled.value=[];selected.value=new Set();await loadProduction()}catch(event:any){error.value=msg(event,'任务创建失败')}finally{working.value=false}}
function updateParam(row:CompiledShotTask,key:string,value:any){row.params={...row.params,[key]:value};if(['prompt','positive_prompt','text','description'].includes(key))row.prompt=String(value||'')}
async function takeAction(action:'select'|'unselect'|'delete'|'review'|'regenerate',take:DramaTake){try{if(action==='select'||action==='unselect')await shortDramaApi.selectTake(projectId.value,take.id,action==='select');else if(action==='delete'){if(!confirm(`删除 Take ${take.take_no}？素材文件仍保留在素材库。`))return;await shortDramaApi.deleteTake(projectId.value,take.id)}else if(action==='review'){const note=prompt('审阅意见',take.review_note||'');if(note===null)return;await shortDramaApi.reviewTake(projectId.value,take.id,note)}else{const note=prompt('返工说明',take.review_note||'');if(note===null)return;await shortDramaApi.regenerateTake(projectId.value,take.id,{review_note:note,parameter_overrides:{},idempotency_key:crypto.randomUUID()});notice.value='返工任务已进入队列'}await loadProduction()}catch(event:any){error.value=msg(event,'操作失败')}}
async function reconcile(taskId:number){try{await shortDramaApi.reconcileProductionTask(projectId.value,taskId);notice.value='产物已重新同步';await loadProduction()}catch(event:any){error.value=msg(event,'同步失败')}}
function openTake(take:DramaTake){preview.value={id:take.resource.id,filename:take.resource.filename,media_type:take.resource.media_type,mime:take.resource.mime,width:take.resource.width,height:take.resource.height,duration:take.resource.duration}}
function toggleCompare(id:number){const next=new Set(compare.value);next.has(id)?next.delete(id):next.add(id);compare.value=next}
watch(generationTypeId,()=>void loadWorkflows())
onMounted(async()=>{await load();poll=setInterval(()=>{if(hasRunning.value)void loadProduction()},4000)})
onBeforeUnmount(()=>{if(poll)clearInterval(poll);Object.values(thumbs.value).forEach(URL.revokeObjectURL)})
</script>

<template><div class="v2-page production-page">
  <header class="page-head"><div><button class="back" @click="router.push(`/v2/drama/projects/${projectId}`)">← 项目概览</button><h1>镜头生产</h1><p>从分镜编译生成参数，执行任务，并在多个 Take 中审阅和采用最终产物。</p></div><div class="head-actions"><V2Button variant="ghost" @click="router.push(`/v2/drama/projects/${projectId}/storyboard`)">分镜工作台</V2Button><V2Button variant="ghost" @click="router.push('/v2/tasks')">任务管理</V2Button></div></header>
  <p v-if="error" class="banner error">{{ error }}</p><p v-if="notice" class="banner notice">{{ notice }}</p>
  <GlassCard class="production-toolbar"><label>生成类型<select v-model.number="generationTypeId"><option v-for="item in types" :key="item.id" :value="item.id">{{ mediaLabel(item.media_type) }} · {{ item.name }}</option></select></label><label>工作流<select v-model.number="workflowVersionId"><option :value="null">使用类型默认工作流</option><option v-for="item in workflows" :key="item.current_version_id" :value="item.current_version_id">{{ item.name }} · V{{ item.current_version_id }}</option></select></label><label>镜头状态<select v-model="filter"><option value="all">全部</option><option value="ready">已就绪</option><option value="draft">草稿</option></select></label><span class="selection">已选 {{ selected.size }} 个</span><V2Button variant="primary" :disabled="working||(!selected.size&&!activeShotId)" @click="compile">{{ working?'处理中…':'编译并预检' }}</V2Button></GlassCard>
  <div v-if="loading" class="empty">正在加载镜头…</div><div v-else class="workspace">
    <aside class="shot-list"><button v-for="item in visible" :key="item.shot.id" :class="{active:item.shot.id===activeShotId}" @click="chooseShot(item.shot.id)"><input type="checkbox" :checked="selected.has(item.shot.id)" @click.stop="toggle(item.shot.id)"><span><b>{{ item.episode.number }}-{{ item.scene.scene_no }}-{{ item.shot.shot_no }}</b><small>{{ item.shot.visual_description||'未填写画面描述' }}</small></span><StatusBadge :tone="item.shot.status==='ready'?'success':'neutral'">{{ item.shot.status==='ready'?'就绪':'草稿' }}</StatusBadge></button><p v-if="!visible.length" class="empty">暂无镜头</p></aside>
    <main class="take-workspace"><section v-if="activeShot" class="shot-summary"><div><small>当前镜头 #{{ activeShot.shot_no }}</small><h2>{{ activeShot.visual_description||'未填写画面描述' }}</h2><p>{{ activeShot.action }} · {{ activeShot.duration }} 秒 · {{ activeShot.camera_movement }}</p></div><StatusBadge :tone="activeShot.status==='ready'?'success':'warning'">{{ activeShot.status==='ready'?'可生产':'需要检查' }}</StatusBadge></section>
      <section class="takes"><header><div><h2>Take 候选</h2><p>一个任务的所有输出都会分别显示，不会遗漏多文件结果。</p></div><span>{{ production?.takes.length||0 }} 个</span></header><div v-if="production?.takes.length" class="take-grid"><article v-for="take in production.takes" :key="take.id" :class="{selected:take.is_selected,compare:compare.has(take.id)}"><button class="media" @click="openTake(take)"><img v-if="thumbs[take.resource_id]" :src="thumbs[take.resource_id]"><span v-else>{{ take.resource.media_type==='audio'?'♪':'正在加载预览' }}</span><i>Take {{ take.take_no }}</i></button><div class="take-copy"><header><StatusBadge :tone="take.is_selected?'success':'neutral'">{{ take.is_selected?'已采用':'候选' }}</StatusBadge><small>{{ take.resource.width&&take.resource.height?`${take.resource.width}×${take.resource.height}`:'' }} {{ take.resource.duration!=null?`· ${take.resource.duration}s`:'' }}</small></header><p>{{ take.review_note||'暂无审阅意见' }}</p><div class="take-actions"><button @click="takeAction(take.is_selected?'unselect':'select',take)">{{ take.is_selected?'取消采用':'采用' }}</button><button @click="toggleCompare(take.id)">{{ compare.has(take.id)?'取消对比':'加入对比' }}</button><button @click="takeAction('review',take)">评价</button><button @click="takeAction('regenerate',take)">返工</button><button :disabled="take.is_selected" @click="takeAction('delete',take)">删除</button></div></div></article></div><div v-else class="empty">当前镜头还没有生成产物</div></section>
      <section v-if="compare.size>1" class="compare-strip"><b>对比栏</b><button v-for="take in production?.takes.filter(item=>compare.has(item.id))" :key="take.id" @click="openTake(take)">Take {{ take.take_no }} · {{ take.resource.width }}×{{ take.resource.height }}</button></section>
      <section class="task-stream"><header><h2>运行记录</h2><span>{{ production?.tasks.length||0 }} 项</span></header><article v-for="item in production?.tasks" :key="item.link.id"><StatusBadge :tone="statusMeta[item.task_status]?.tone||'neutral'">{{ statusMeta[item.task_status]?.label||item.task_status }}</StatusBadge><b>任务 #{{ item.link.task_id }}</b><span>{{ item.link.purpose==='regenerate'?'返工':'生成' }}</span><em :class="item.link.status">{{ item.link.status==='synced'?'Take 已同步':item.link.status==='linked'?'等待执行':item.link.status }}</em><small v-if="item.link.sync_error">{{ item.link.sync_error }}</small><button v-if="item.task_status==='SUCCESS'&&item.link.status!=='synced'" @click="reconcile(item.link.task_id)">重新同步</button></article><p v-if="!production?.tasks.length" class="empty">暂无运行记录</p></section>
    </main>
  </div>
  <section v-if="compiled.length" class="compile-panel"><header><div><h2>执行前检查</h2><p>每个镜头保留独立提示词与参数；修改不会影响其他镜头。</p></div><div><V2Button variant="ghost" @click="compiled=[]">取消</V2Button><V2Button variant="primary" :disabled="working||compiled.some(item=>item.validation_errors.length>0)" @click="createTasks">确认执行 {{ compiled.length }} 个镜头</V2Button></div></header><div class="compile-grid"><article v-for="row in compiled" :key="row.shot_id"><header><b>镜头 #{{ shots.find(item=>item.shot.id===row.shot_id)?.shot.shot_no }}</b><span>{{ row.workflow_name }}</span></header><p v-for="issue in row.validation_errors" :key="issue.path" class="issue">{{ issue.message }}</p><label v-for="(value,key) in row.params" :key="key"><span>{{ key }}</span><textarea v-if="typeof value==='string'&&String(value).length>60" :value="value" rows="4" @input="updateParam(row,String(key),($event.target as HTMLTextAreaElement).value)"></textarea><input v-else-if="typeof value==='number'" type="number" :value="value" @input="updateParam(row,String(key),Number(($event.target as HTMLInputElement).value))"><input v-else :value="typeof value==='object'?JSON.stringify(value):String(value??'')" @input="updateParam(row,String(key),($event.target as HTMLInputElement).value)"></label></article></div></section>
  <MediaViewer :open="!!preview" :output="preview" @close="preview=null"/>
</div></template>

<style scoped>
.production-page{display:grid;gap:14px}.page-head,.production-toolbar,.shot-summary,.takes>header,.task-stream>header,.compile-panel>header{display:flex;align-items:center;justify-content:space-between;gap:14px}.page-head h1{margin:8px 0 3px;font-size:30px}.page-head p,.takes header p,.compile-panel header p{margin:0;color:var(--v2-text-muted)}.back{padding:0;color:var(--v2-text-muted);background:none;border:0}.head-actions{display:flex;gap:8px}.banner{margin:0;padding:10px 13px;border-radius:10px}.banner.error,.issue{color:var(--v2-danger);background:rgba(255,90,110,.1)}.banner.notice{color:var(--v2-success);background:rgba(60,210,150,.08)}.production-toolbar{padding:10px;justify-content:flex-start;flex-wrap:wrap}.production-toolbar label{display:grid;gap:4px;color:var(--v2-text-muted);font-size:11px}.production-toolbar select,.compile-panel input,.compile-panel textarea{min-width:170px;padding:9px;color:var(--v2-text);background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:8px}.selection{margin-left:auto;color:var(--v2-text-muted)}.workspace{min-height:640px;display:grid;grid-template-columns:280px minmax(0,1fr);overflow:hidden;background:var(--v2-surface);border:1px solid var(--v2-border);border-radius:16px}.shot-list{padding:9px;overflow:auto;border-right:1px solid var(--v2-border)}.shot-list>button{width:100%;padding:10px;display:grid;grid-template-columns:24px minmax(0,1fr) auto;align-items:center;gap:8px;text-align:left;color:var(--v2-text);background:none;border:0;border-radius:10px}.shot-list>button.active{background:rgba(120,130,255,.14)}.shot-list span{min-width:0;display:grid;gap:4px}.shot-list small{overflow:hidden;color:var(--v2-text-muted);text-overflow:ellipsis;white-space:nowrap}.take-workspace{padding:16px;display:grid;align-content:start;gap:18px;overflow:auto}.shot-summary{padding-bottom:14px;border-bottom:1px solid var(--v2-border)}.shot-summary h2{margin:4px 0;font-size:20px}.shot-summary p{margin:0;color:var(--v2-text-muted)}.takes h2,.task-stream h2,.compile-panel h2{margin:0}.take-grid{margin-top:12px;display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:11px}.take-grid article{overflow:hidden;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:13px}.take-grid article.selected{border-color:var(--v2-success)}.take-grid article.compare{box-shadow:0 0 0 2px rgba(135,120,255,.45)}.media{width:100%;aspect-ratio:2/3;max-height:280px;position:relative;display:grid;place-items:center;overflow:hidden;color:var(--v2-text-muted);background:rgba(0,0,0,.18);border:0}.media img{width:100%;height:100%;object-fit:cover}.media i{position:absolute;left:8px;bottom:8px;padding:4px 7px;color:white;background:rgba(0,0,0,.65);border-radius:6px;font-style:normal}.take-copy{padding:10px}.take-copy header{display:flex;align-items:center;justify-content:space-between}.take-copy p{min-height:32px;color:var(--v2-text-muted);font-size:12px}.take-actions{display:flex;flex-wrap:wrap;gap:5px}.take-actions button,.task-stream article button,.compare-strip button{padding:5px 7px;color:var(--v2-text-muted);background:none;border:1px solid var(--v2-border);border-radius:6px}.task-stream{padding-top:14px;border-top:1px solid var(--v2-border)}.task-stream article{padding:9px;display:grid;grid-template-columns:auto auto auto 1fr auto;align-items:center;gap:8px;border-bottom:1px solid var(--v2-border)}.task-stream em{justify-self:end;color:var(--v2-text-muted);font-style:normal}.task-stream em.synced{color:var(--v2-success)}.task-stream small{grid-column:2/-1;color:var(--v2-danger)}.compare-strip{padding:10px;display:flex;align-items:center;gap:7px;overflow:auto;background:rgba(125,130,255,.08);border-radius:10px}.compile-panel{position:fixed;z-index:30;inset:76px 22px 18px 260px;padding:18px;overflow:auto;background:rgba(16,20,30,.96);backdrop-filter:blur(24px);border:1px solid var(--v2-border);border-radius:17px;box-shadow:0 24px 80px rgba(0,0,0,.45)}.compile-panel>header>div:last-child{display:flex;gap:8px}.compile-grid{margin-top:15px;display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:12px}.compile-grid article{padding:13px;background:var(--v2-surface-soft);border:1px solid var(--v2-border);border-radius:12px}.compile-grid article>header{display:flex;justify-content:space-between;margin-bottom:10px}.compile-grid article>header span{color:var(--v2-text-muted)}.compile-grid label{margin-top:8px;display:grid;gap:4px;color:var(--v2-text-muted);font-size:11px}.compile-grid input,.compile-grid textarea{width:100%}.issue{padding:7px;border-radius:7px}.empty{padding:40px;text-align:center;color:var(--v2-text-muted)}
@media(max-width:900px){.workspace{grid-template-columns:220px minmax(0,1fr)}.compile-panel{inset:68px 12px 12px}.take-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.page-head{align-items:flex-start;flex-direction:column}.head-actions{width:100%;flex-wrap:wrap}.selection{margin-left:0}.workspace{display:block}.shot-list{max-height:240px;border-right:0;border-bottom:1px solid var(--v2-border)}.take-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.media{max-height:210px}.compile-panel{inset:8px}.compile-panel>header{align-items:flex-start;flex-direction:column}.compile-grid{grid-template-columns:1fr}.task-stream article{grid-template-columns:auto 1fr auto}.task-stream article span{display:none}}
</style>
